1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** What each item is insured for; distinct from what it costs to insure. */
61	const INSURANCE_VALUES: Record<string, number | undefined> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
72	
73	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
74	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
75	
76	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
77	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
78	
79	/** Payouts are rounded in the MHPCO's favour too — which for money paid out is down. */
80	const roundDownToWholeG = (amount: number): number => Math.floor(withoutFloatNoise(amount));
81	
82	/** Every price list is keyed by item type, and an unlisted type is never priceable. */
83	const listedAmountFor = (priceList: Record<string, number | undefined>) =>
84	  (item: Item): number => {
85	    const amount = priceList[item.type];
86	    if (amount === undefined) throw new Error(`Unknown item type: ${item.type}`);
87	    return amount;
88	  };
89	
90	const basePremiumFor = listedAmountFor(BASE_PREMIUMS);
91	const insuranceValueFor = listedAmountFor(INSURANCE_VALUES);
92	
93	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
94	  values.reduce((total, value) => total + amountOf(value), 0);
95	
96	/** A building block of 3 alike components is offered at a special base premium. */
97	const BLOCK_SIZE = 3;
98	const BLOCK_BASE_PREMIUM = 60;
99	
100	/** Components are the small parts; main items never qualify for block pricing. */
101	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
102	
103	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
104	
105	/** Block pricing is decided per type, so items are priced in same-type groups. */
106	const groupedByType = (items: Item[]): Item[][] => [
107	  ...items
108	    .reduce(
109	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	const isBlock = (group: Item[]): boolean =>
116	  group.length === BLOCK_SIZE && group.every(isComponent);
117	
118	const basePremiumForGroup = (group: Item[]): number =>
119	  isBlock(group) ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
120	
121	const HIGH_ENCHANTMENT_THRESHOLD = 5;
122	
123	const isCursed = (item: Item): boolean => item.cursed === true;
124	
125	const isHighlyEnchanted = (item: Item): boolean =>
126	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
127	
128	/**
129	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
130	 * subjects it applies to. Modifiers that apply stack additively.
131	 */
132	interface Modifier<Subject> {
133	  appliesTo: (subject: Subject) => boolean;
134	  rate: number;
135	}
136	
137	const combinedRateOf = <Subject>(
138	  modifiers: Modifier<Subject>[],
139	  subject: Subject,
140	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
141	
142	/** Item-specific modifiers are levied on the affected item's own base premium. */
143	const ITEM_MODIFIERS: Modifier<Item>[] = [
144	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
145	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
146	];
147	
148	const itemSurchargeFor = (item: Item): number =>
149	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
150	
151	const LOYALTY_THRESHOLD_YEARS = 2;
152	
153	/**
154	 * The circumstances a single quote is issued under: who is being quoted, and
155	 * where this contract falls in their history with the MHPCO. Policy-wide
156	 * modifiers are decided from this alone.
157	 */
158	interface QuoteContext {
159	  customer: Customer;
160	  isFollowUpContract: boolean;
161	}
162	
163	const isLongStanding = ({ customer }: QuoteContext): boolean =>
164	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
165	
166	const followsAnEarlierContract = ({ isFollowUpContract }: QuoteContext): boolean =>
167	  isFollowUpContract;
168	
169	const appliesToEveryQuote = (): boolean => true;
170	
171	/** Policy-wide modifiers are levied on the whole policy's base premium. */
172	const POLICY_MODIFIERS: Modifier<QuoteContext>[] = [
173	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
174	  { appliesTo: appliesToEveryQuote, rate: INITIAL_ASSESSMENT_SURCHARGE },
175	  { appliesTo: followsAnEarlierContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
176	];
177	
178	/**
179	 * Item-specific modifiers are levied on the affected item's own base premium,
180	 * while policy-wide modifiers are levied on the policy base premium — the sum
181	 * of the item base premiums, before any item surcharge is added.
182	 */
183	const quote = (step: QuoteStep, context: QuoteContext): StepResult => {
184	  const policyBasePremium = sumOf(groupedByType(step.items), basePremiumForGroup);
185	  const itemSurcharges = sumOf(step.items, itemSurchargeFor);
186	  const policyAdjustment = policyBasePremium * combinedRateOf(POLICY_MODIFIERS, context);
187	  return {
188	    premium: roundUpToWholeG(
189	      policyBasePremium + itemSurcharges + policyAdjustment + PROCESSING_FEE,
190	    ),
191	  };
192	};
193	
194	/** A policy created by a quote step, against which later claims are settled. */
195	interface Policy {
196	  items: Item[];
197	  remainingCap: number;
198	}
199	
200	const policyFor = (step: QuoteStep): Policy => ({
201	  items: step.items,
202	  remainingCap: sumOf(step.items, insuranceValueFor) * CAP_MULTIPLE_OF_INSURANCE_SUM,
203	});
204	
205	/**
206	 * Damage to a very strongly enchanted item is only half reimbursed. This
207	 * threshold is deliberately distinct from the premium side's
208	 * HIGH_ENCHANTMENT_THRESHOLD: the same attribute is read by two unrelated rules.
209	 */
210	const ENCHANTMENT_HALVING_REIMBURSEMENT = 8;
211	const HALF_REIMBURSEMENT_RATE = 0.5;
212	const FULL_REIMBURSEMENT_RATE = 1;
213	
214	const isTooEnchantedToFullyReimburse = (item: Item): boolean =>
215	  item.enchantment !== undefined && item.enchantment >= ENCHANTMENT_HALVING_REIMBURSEMENT;
216	
217	const reimbursementRateFor = (item: Item): number =>
218	  isTooEnchantedToFullyReimburse(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
219	
220	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
221	  const item = policy.items.find(({ type }) => type === damage.itemType);
222	  if (item === undefined) throw new Error(`Item not insured: ${damage.itemType}`);
223	  return item;
224	};
225	
226	/**
227	 * The clause is applied to the damage first; the deductible comes off the result.
228	 * The deductible can reduce an entry to nothing but never below it, so a damage
229	 * smaller than the deductible pays nothing rather than clawing back from the
230	 * other damages in the same incident.
231	 */
232	const deductedReimbursementFor = (damage: Damage, policy: Policy): number => {
233	  const reimbursed = damage.amount * reimbursementRateFor(insuredItemFor(damage, policy));
234	  return Math.max(reimbursed - DEDUCTIBLE_PER_DAMAGE, 0);
235	};
236	
237	/** Claims name the quote step that created the policy they are settled against. */
238	const policyAt = (policies: Map<number, Policy>, step: number): Policy => {
239	  const policy = policies.get(step);
240	  if (policy === undefined) throw new Error(`No policy at step ${step}`);
241	  return policy;
242	};
243	
244	/**
245	 * A claim both reports a payout and draws down the policy's cap, so settling one
246	 * yields the settled policy rather than mutating it: successive claims against
247	 * the same policy are then an explicit chain, not a hidden shared-state effect.
248	 */
249	const claim = (
250	  step: ClaimStep,
251	  policy: Policy,
252	): { result: StepResult; policy: Policy } => {
253	  const reimbursementBeforeCap = sumOf(step.incident.damages, (damage) =>
254	    deductedReimbursementFor(damage, policy),
255	  );
256	  const payout = roundDownToWholeG(Math.min(reimbursementBeforeCap, policy.remainingCap));
257	  const remainingCap = policy.remainingCap - payout;
258	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
259	};
260	
261	/**
262	 * Steps are not independent: a quote's premium depends on whether an earlier
263	 * quote in the same scenario already established a contract, and a claim is
264	 * settled against the policy an earlier quote created.
265	 */
266	export const runScenario = (scenario: Scenario): ScenarioResult => {
267	  const policies = new Map<number, Policy>();
268	  let hasQuoted = false;
269	
270	  const results = scenario.steps.map((step, index) => {
271	    if (step.op === "quote") {
272	      const result = quote(step, {
273	        customer: scenario.customer,
274	        isFollowUpContract: hasQuoted,
275	      });
276	      policies.set(index, policyFor(step));
277	      hasQuoted = true;
278	      return result;
279	    }
280	
281	    const { result, policy: settledPolicy } = claim(step, policyAt(policies, step.policy));
282	    policies.set(step.policy, settledPolicy);
283	    return result;
284	  });
285	
286	  return { results };
287	};
